mapper.select:
SELECT author_id, score
FROM user_author_affinity
WHERE viewer_id = #{viewerId}
ORDER BY score DESC
LIMIT #{limit}

SELECT item_type, item_id, seen_count, opened, last_seen_at
FROM feed_impressions
WHERE user_id = #{viewerId} AND last_seen_at > #{since}
ORDER BY last_seen_at DESC
LIMIT #{limit}

SELECT item_type, item_id, COUNT(DISTINCT user_id) AS people
FROM (
    SELECT 'CHECKIN'::varchar AS item_type, l.checkin_id AS item_id, l.user_id
    FROM user_checkin_likes l
    WHERE l.user_id IN #{id}
      AND l.created_at > #{since}
    UNION ALL
    SELECT 'REVIEW'::varchar, v.review_id, v.user_id
    FROM review_helpful_votes v
    WHERE v.user_id IN #{id}
      AND v.is_helpful AND v.created_at > #{since}
    UNION ALL
    SELECT 'TRIP'::varchar, v.trip_id, v.user_id
    FROM trip_helpful_votes v
    WHERE v.user_id IN #{id}
      AND v.is_helpful AND v.created_at > #{since}
    UNION ALL
    SELECT c.content_type::varchar, c.content_id, c.user_id
    FROM content_comments c
    WHERE c.user_id IN #{id}
      AND c.is_deleted = FALSE
      AND c.content_type IN ('CHECKIN', 'REVIEW', 'TRIP')
      AND c.created_at > #{since}
    UNION ALL
    SELECT s.post_type::varchar, s.post_id, s.user_id
    FROM saved_posts s
    WHERE s.user_id IN #{id}
      AND s.created_at > #{since}
) touched
GROUP BY item_type, item_id
ORDER BY people DESC, item_id
LIMIT #{limit}
